#include <iostream>
#include <regex>
using namespace std;

int main() {
    // 读取输入字符串
    string s;
    cin >> s;

    // 定义匹配非法字符的正则表达式（非数字和小写字母的字符）
    string pat = "[^0-9a-z]";

    // 用于存储数字部分的字符串
    string num = "";

    // 用于存储最终解压缩的结果
    string res = "";

    // 如果字符串包含非法字符，则输出 "!error"
    if (regex_search(s, regex(pat))) {
        res = "!error";
    } else {
        // 遍历输入字符串的每一个字符
        for (char c : s) {
            // 如果当前字符是数字，则将其追加到 num 中
            if (isdigit(c)) {
                num += c;
            } 
            // 如果 num 不为空，表示之前有数字，需要进行解压操作
            else if (num != "") {
                // 判断数字是否小于等于2，如果是则输入不合法
                if (stoi(num) <= 2) {
                    res = "!error";
                    break;
                } else {
                    // 将对应数量的字母添加到结果中
                    res += string(stoi(num), c);
                    // 重置 num 为空
                    num = "";
                }
            } 
            // 如果当前字符是字母，且前面没有数字，则直接添加到结果中
            else {
                res += c;
            }
        }
    }

    // 输出最终结果
    cout << res << endl;
    return 0;
}
