#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>
#include <stdbool.h>

// 定义一个函数，用于检查字符串中是否包含非法字符
bool contains_invalid_characters(const char *s) {
    while (*s) {
        // 如果字符不是数字或小写字母，则认为是非法字符
        if (!isdigit(*s) && !islower(*s)) {
            return true;
        }
        s++;
    }
    return false;
}

int main() {
    // 定义存储输入字符串的数组
    char s[1000];

    // 读取输入字符串
    scanf("%s", s);

    // 用于存储数字部分的字符串
    char num[100] = "";

    // 用于存储最终解压缩的结果
    char res[1000] = "";

    // 如果字符串包含非法字符，则输出 "!error"
    if (contains_invalid_characters(s)) {
        strcpy(res, "!error");
    } else {
        // 遍历输入字符串的每一个字符
        for (int i = 0; s[i] != '\0'; i++) {
            char c = s[i];

            // 如果当前字符是数字，则将其追加到 num 中
            if (isdigit(c)) {
                strncat(num, &c, 1);
            } 
            // 如果 num 不为空，表示之前有数字，需要进行解压操作
            else if (strlen(num) > 0) {
                // 判断数字是否小于等于2，如果是则输入不合法
                int repeat_count = atoi(num);
                if (repeat_count <= 2) {
                    strcpy(res, "!error");
                    break;
                } else {
                    // 将对应数量的字母添加到结果中
                    for (int j = 0; j < repeat_count; j++) {
                        strncat(res, &c, 1);
                    }
                    // 重置 num 为空
                    num[0] = '\0';
                }
            } 
            // 如果当前字符是字母，且前面没有数字，则直接添加到结果中
            else {
                strncat(res, &c, 1);
            }
        }
    }

    // 输出最终结果
    printf("%s\n", res);
    return 0;
}
